<?php
namespace Tests\Feature;
use App\Models\{Owner,User,Venue,GatewayAccount,CheckoutAttempt,BookingPayment};use App\Services\{VenueSettings,BookingEngine};use App\Services\Payments\{GatewayDriver,PaymentService};use Illuminate\Foundation\Testing\RefreshDatabase;use Illuminate\Support\Facades\{DB,Hash,Http};use Illuminate\Support\Str;use Tests\TestCase;
class AccessPaymentTest extends TestCase {
 use RefreshDatabase;
 private function owner():Owner{$u=User::factory()->create();return Owner::unguarded(fn()=>Owner::create(['user_id'=>$u->id,'name'=>'Propietario','email'=>$u->email,'password'=>'OwnerPassword12345','activated'=>true,'email_verified_at'=>now()]));}
 private function venue(?Owner $o=null):Venue{$o??=$this->owner();return Venue::create(['owner_id'=>$o->user_id,'owner_account_id'=>$o->id,'name'=>'Jardín real','slug'=>'jardin-'.Str::lower(Str::random(6)),'published'=>true,'settings'=>array_replace(VenueSettings::defaults(),['capacity'=>100,'open_hour'=>10,'close_hour'=>26,'prep_minutes'=>0,'clean_minutes'=>120,'included_hours'=>8,'weekday_price'=>650000,'weekend_price'=>850000,'holiday_price'=>1050000,'extra_hour_price'=>85000,'deposit_value'=>30,'address'=>'Colima','lat'=>19.2,'lng'=>-103.7])]);}
 private function booking(Venue $v,?User $u=null){$u??=User::factory()->create();return app(BookingEngine::class)->reserve($v,$u->id,['date'=>now('America/Mexico_City')->addMonth()->startOfWeek()->addDays(2)->format('Y-m-d'),'start'=>14,'hours'=>8,'guests'=>50]);}
 private function account(Venue $v,string $provider='mercadopago'):GatewayAccount{return GatewayAccount::create(['venue_id'=>$v->id,'provider'=>$provider,'enabled'=>true,'sandbox'=>true,'credentials'=>['access_token'=>'test-token','webhook_secret'=>'test-signature-secret','merchant_id'=>'12345','client_id'=>'test-client','client_secret'=>'test-secret','webhook_id'=>'test-webhook']]);}
 private function attempt($b,$g):CheckoutAttempt{return CheckoutAttempt::create(['id'=>(string)Str::uuid(),'booking_id'=>$b->id,'gateway_account_id'=>$g->id,'provider'=>$g->provider,'amount'=>$b->deposit,'currency'=>'MXN','status'=>'pending','external_id'=>$g->provider==='mercadopago'?'pref-test':'order-test','expires_at'=>now()->addMinutes(15)]);}
 private function mpData($a,array $override=[]):array{return array_replace(['id'=>777,'status'=>'approved','live_mode'=>false,'external_reference'=>$a->id,'transaction_amount'=>$a->amount/100,'transaction_amount_refunded'=>0,'currency_id'=>'MXN','collector_id'=>12345],$override);}
 private function mpNotify($v,$g,$id=777,$versioned=false){$ts=(string)time();$rid='test-request';$sig=hash_hmac('sha256',"id:$id;request-id:$rid;ts:$ts;",$g->credentials['webhook_secret']);return $this->postJson('/api/payments/webhooks/'.$v->slug.'/mercadopago'.($versioned?'/'.$g->id:'').'?data.id='.$id,['type'=>'payment','data'=>['id'=>(string)$id]],['x-request-id'=>$rid,'x-signature'=>'ts='.$ts.',v1='.$sig]);}
 public function test_customer_cannot_create_or_read_owner_venues_even_with_role_in_payload():void{$u=User::factory()->create();$this->actingAs($u)->postJson('/api/owner/venues',['role'=>'owner'])->assertForbidden();$this->getJson('/api/owner/venues')->assertForbidden();$this->get('/gestion')->assertNotFound();}
 public function test_owner_cannot_access_customer_booking_routes():void{$o=$this->owner();$this->actingAs($o)->getJson('/api/bookings')->assertForbidden();$this->postJson('/api/register',['role'=>'owner'])->assertForbidden();$this->get('/account')->assertNotFound();}
 public function test_owner_registration_requires_valid_invitation_and_is_single_use():void{config(['portal.kind'=>'owner']);$token=Str::random(64);DB::table('owner_invitations')->insert(['email'=>'propietario@example.com','token_hash'=>hash('sha256',$token),'expires_at'=>now()->addHour(),'created_at'=>now(),'updated_at'=>now()]);$data=['name'=>'Propietario','email'=>'propietario@example.com','password'=>'OwnerPassword12345','password_confirmation'=>'OwnerPassword12345','invitation'=>$token];$this->postJson('/api/owner-auth/register',$data)->assertCreated();$this->assertAuthenticated('owner');$this->assertSame(1,Owner::count());$this->postJson('/api/owner-auth/register',$data)->assertUnprocessable();$this->assertSame(1,Owner::count());}
 public function test_owner_self_registration_stays_separate_from_customer_signup():void{config(['portal.owner_registration'=>'open']);config(['portal.kind'=>'owner']);$this->postJson('/api/owner-auth/register',['name'=>'Persona','email'=>'persona@example.com','password'=>'OwnerPassword12345','password_confirmation'=>'OwnerPassword12345'])->assertCreated();config(['portal.kind'=>'client']);$this->postJson('/api/register',['name'=>'Cliente','email'=>'cliente@example.com','password'=>'CustomerPassword123','password_confirmation'=>'CustomerPassword123','role'=>'owner'])->assertCreated();$this->assertSame(1,Owner::count());}
 public function test_customer_credentials_do_not_authenticate_owner_guard():void{$u=User::factory()->create(['email'=>'same@example.com','password'=>'CustomerPassword123']);Owner::unguarded(fn()=>Owner::create(['user_id'=>$u->id,'name'=>'Propietario','email'=>'same@example.com','password'=>'OwnerPassword12345','activated'=>true,'email_verified_at'=>now()]));config(['portal.kind'=>'owner']);$this->postJson('/api/owner-auth/login',['email'=>'same@example.com','password'=>'CustomerPassword123'])->assertUnprocessable();$this->postJson('/api/owner-auth/login',['email'=>'same@example.com','password'=>'OwnerPassword12345'])->assertOk();}
 public function test_owner_can_only_manage_own_establishments():void{$v=$this->venue();$other=$this->owner();$this->actingAs($other)->getJson('/api/owner/venues/'.$v->slug.'/bookings')->assertForbidden();$this->getJson('/api/owner/venues')->assertJsonCount(0);}
 public function test_checkout_charges_server_deposit_and_reuses_pending_attempt():void{$v=$this->venue();$u=User::factory()->create();$b=$this->booking($v,$u);$g=$this->account($v);Http::fake(['api.mercadopago.com/checkout/preferences'=>Http::response(['id'=>'pref-test','collector_id'=>12345,'sandbox_init_point'=>'https://sandbox.mercadopago.com.mx/checkout/test'])]);$this->actingAs($u);$data=['policy_accepted'=>true,'provider'=>'mercadopago','purpose'=>'deposit','amount'=>1];$a=$this->postJson('/api/bookings/'.$b->id.'/checkout',$data)->assertOk()->assertJsonPath('amount',$b->deposit)->json();$this->postJson('/api/bookings/'.$b->id.'/checkout',$data)->assertOk()->assertJsonPath('id',$a['id']);Http::assertSentCount(1);$this->assertSame(0,$b->payments()->count());}
 public function test_other_customer_cannot_pay_or_read_checkout():void{$v=$this->venue();$b=$this->booking($v);$g=$this->account($v);$a=$this->attempt($b,$g);$this->actingAs(User::factory()->create())->getJson('/api/checkout/'.$a->id)->assertForbidden();$this->postJson('/api/bookings/'.$b->id.'/checkout',['policy_accepted'=>true,'provider'=>'mercadopago','purpose'=>'deposit'])->assertForbidden();}
 public function test_fake_webhook_is_rejected_without_provider_lookup():void{$v=$this->venue();$b=$this->booking($v);$g=$this->account($v);$this->attempt($b,$g);Http::fake();$this->postJson('/api/payments/webhooks/'.$v->slug.'/mercadopago',['data'=>['id'=>'777']],['x-signature'=>'bad'])->assertUnauthorized();Http::assertNothingSent();$this->assertSame(0,$b->payments()->count());}
 public function test_signed_mercado_pago_payment_is_confirmed_once():void{$v=$this->venue();$b=$this->booking($v);$g=$this->account($v);$a=$this->attempt($b,$g);Http::fake(['api.mercadopago.com/v1/payments/777'=>Http::response($this->mpData($a))]);$this->mpNotify($v,$g)->assertOk();$this->mpNotify($v,$g)->assertOk();$this->assertSame(1,$b->payments()->count());$this->assertSame('confirmed',$b->fresh()->status);$this->assertSame($b->deposit,$b->fresh()->paid_total);}
 public function test_wrong_amount_and_wrong_receiver_never_confirm_reservation():void{$v=$this->venue();$b=$this->booking($v);$g=$this->account($v);$a=$this->attempt($b,$g);$sequence=Http::sequence();foreach([['transaction_amount'=>1],['collector_id'=>99999],['currency_id'=>'USD'],['live_mode'=>true]] as $bad)$sequence->push($this->mpData($a,$bad));Http::fake(['api.mercadopago.com/v1/payments/777'=>$sequence]);for($i=0;$i<4;$i++)$this->mpNotify($v,$g)->assertUnprocessable();$this->assertSame(0,$b->payments()->count());}
 public function test_pending_payment_never_counts_as_money_received():void{$v=$this->venue();$b=$this->booking($v);$g=$this->account($v);$a=$this->attempt($b,$g);Http::fake(['api.mercadopago.com/v1/payments/777'=>Http::response($this->mpData($a,['status'=>'pending']))]);$this->mpNotify($v,$g)->assertOk();$this->assertSame(0,$b->payments()->count());$this->assertSame('hold',$b->fresh()->status);}
 public function test_late_payment_is_recorded_but_does_not_take_occupied_slot():void{$v=$this->venue();$b=$this->booking($v);$g=$this->account($v);$a=$this->attempt($b,$g);$b->update(['expires_at'=>now()->subMinute()]);$new=$this->booking($v);Http::fake(['api.mercadopago.com/v1/payments/777'=>Http::response($this->mpData($a))]);$this->mpNotify($v,$g)->assertOk();$this->assertSame('review',$a->fresh()->status);$this->assertNotNull($b->fresh()->payment_attention);$this->assertSame('hold',$b->fresh()->status);$this->assertSame(1,$b->payments()->count());}
 public function test_refund_reduces_received_money_once():void{$v=$this->venue();$b=$this->booking($v);$g=$this->account($v);$a=$this->attempt($b,$g);Http::fake(['api.mercadopago.com/v1/payments/777'=>Http::sequence()->push($this->mpData($a))->push($this->mpData($a,['status'=>'refunded','transaction_amount_refunded'=>$a->amount/100]))->push($this->mpData($a,['status'=>'refunded','transaction_amount_refunded'=>$a->amount/100]))]);$this->mpNotify($v,$g)->assertOk();$this->mpNotify($v,$g)->assertOk();$this->mpNotify($v,$g)->assertOk();$this->assertSame(0,$b->fresh()->paid_total);$this->assertSame(2,$b->payments()->count());$this->assertSame('confirmed',$b->fresh()->status);}
 public function test_paypal_order_and_capture_are_verified_on_server():void{$v=$this->venue();$u=User::factory()->create();$b=$this->booking($v,$u);$g=$this->account($v,'paypal');$a=$this->attempt($b,$g);$order=['id'=>'order-test','status'=>'COMPLETED','purchase_units'=>[['custom_id'=>$a->id,'payee'=>['merchant_id'=>'12345'],'amount'=>['currency_code'=>'MXN','value'=>number_format($a->amount/100,2,'.','')],'payments'=>['captures'=>[['id'=>'capture-test','status'=>'COMPLETED','amount'=>['currency_code'=>'MXN','value'=>number_format($a->amount/100,2,'.','')]]]]]]];Http::fake(['api-m.sandbox.paypal.com/v1/oauth2/token'=>Http::response(['access_token'=>'test-oauth']),'api-m.sandbox.paypal.com/v2/checkout/orders/order-test/capture'=>Http::response($order),'api-m.sandbox.paypal.com/v2/checkout/orders/order-test'=>Http::response($order)]);$this->actingAs($u)->postJson('/api/checkout/'.$a->id.'/capture')->assertOk()->assertJsonPath('status','paid');$this->assertSame(1,$b->payments()->count());}
 public function test_oxxo_creates_reference_without_marking_paid():void{$v=$this->venue();$u=User::factory()->create(['phone'=>'+523121234567']);$b=$this->booking($v,$u);$g=$this->account($v,'oxxo');$g->credentials=['private_key'=>'test-femsa','webhook_public_key'=>'test-public'];$g->save();Http::fake(['api.digitalfemsa.io/orders'=>Http::response(['id'=>'ord_test','livemode'=>false,'charges'=>['data'=>[['payment_method'=>['reference'=>'1234567890']]]]])]);$this->actingAs($u)->postJson('/api/bookings/'.$b->id.'/checkout',['policy_accepted'=>true,'provider'=>'oxxo','purpose'=>'deposit'])->assertOk()->assertJsonPath('checkout.reference','1234567890')->assertJsonPath('status','pending');$this->assertSame(0,$b->payments()->count());$this->assertTrue($b->fresh()->expires_at->gt(now()->addHours(23)));}
 public function test_webhook_cannot_apply_payment_to_other_gateway_account():void{$v=$this->venue();$b=$this->booking($v);$g=$this->account($v);$a=$this->attempt($b,$g);$other=$this->venue();$otherG=$this->account($other);Http::fake(['api.mercadopago.com/v1/payments/777'=>Http::response($this->mpData($a))]);$this->mpNotify($other,$otherG)->assertOk();$this->assertSame(0,$b->payments()->count());}
 public function test_payment_credentials_are_hidden_from_owner_api_and_public_data():void{$v=$this->venue();$g=$this->account($v);$this->actingAs($v->owner)->getJson('/api/owner/venues/'.$v->slug.'/gateways')->assertOk()->assertJsonMissingPath('0.credentials')->assertJsonMissingPath('0.public_fields.access_token');$this->assertNotEquals('test-token',$g->getRawOriginal('credentials'));$this->getJson('/api/venues/'.$v->slug)->assertJsonMissingPath('gateways');}

 public function test_expired_invitation_is_rejected():void{config(['portal.kind'=>'owner']);$token=Str::random(64);DB::table('owner_invitations')->insert(['email'=>'owner@example.com','token_hash'=>hash('sha256',$token),'expires_at'=>now()->subMinute(),'created_at'=>now(),'updated_at'=>now()]);$this->postJson('/api/owner-auth/register',['name'=>'Propietario','email'=>'owner@example.com','password'=>'OwnerPassword12345','password_confirmation'=>'OwnerPassword12345','invitation'=>$token])->assertUnprocessable();$this->assertSame(0,Owner::count());}
 public function test_header_cannot_switch_public_app_into_owner_portal():void{$this->actingAs(User::factory()->create())->getJson('/api/owner/venues',['X-Portal'=>'owner','X-Forwarded-Port'=>'8081'])->assertForbidden();}
 public function test_paypal_does_not_capture_again_when_order_already_paid():void{$v=$this->venue();$u=User::factory()->create();$b=$this->booking($v,$u);$g=$this->account($v,'paypal');$a=$this->attempt($b,$g);$order=['id'=>'order-test','status'=>'COMPLETED','purchase_units'=>[['custom_id'=>$a->id,'payee'=>['merchant_id'=>'12345'],'payments'=>['captures'=>[['id'=>'capture-paid','status'=>'COMPLETED','amount'=>['currency_code'=>'MXN','value'=>number_format($a->amount/100,2,'.','')]]]]]]];Http::fake(['api-m.sandbox.paypal.com/v1/oauth2/token'=>Http::response(['access_token'=>'test-token']),'api-m.sandbox.paypal.com/v2/checkout/orders/order-test'=>Http::response($order)]);$this->actingAs($u)->postJson('/api/checkout/'.$a->id.'/capture')->assertOk()->assertJsonPath('status','paid');Http::assertNotSent(fn($r)=>str_ends_with($r->url(),'/capture'));}
 public function test_capture_is_not_issued_if_slot_became_occupied():void{$v=$this->venue();$u=User::factory()->create();$b=$this->booking($v,$u);$g=$this->account($v,'paypal');$a=$this->attempt($b,$g);$b->update(['expires_at'=>now()->subMinute()]);$this->booking($v);$order=['id'=>'order-test','status'=>'APPROVED','purchase_units'=>[['custom_id'=>$a->id,'payee'=>['merchant_id'=>'12345'],'amount'=>['currency_code'=>'MXN','value'=>number_format($a->amount/100,2,'.','')]]]];Http::fake(['api-m.sandbox.paypal.com/v1/oauth2/token'=>Http::response(['access_token'=>'test-token']),'api-m.sandbox.paypal.com/v2/checkout/orders/order-test'=>Http::response($order)]);$this->actingAs($u)->postJson('/api/checkout/'.$a->id.'/capture')->assertUnprocessable();Http::assertNotSent(fn($r)=>str_ends_with($r->url(),'/capture'));$this->assertSame(0,$b->payments()->count());}
 public function test_paypal_rejects_notification_when_signature_verifier_fails():void{$v=$this->venue();$b=$this->booking($v);$g=$this->account($v,'paypal');$this->attempt($b,$g);Http::fake(['api-m.sandbox.paypal.com/v1/oauth2/token'=>Http::response(['access_token'=>'test-token']),'api-m.sandbox.paypal.com/v1/notifications/verify-webhook-signature'=>Http::response(['verification_status'=>'FAILURE'])]);$headers=['paypal-auth-algo'=>'SHA256withRSA','paypal-cert-url'=>'https://api.paypal.com/cert','paypal-transmission-id'=>'test','paypal-transmission-sig'=>'invalid','paypal-transmission-time'=>now()->toIso8601String()];$this->postJson('/api/payments/webhooks/'.$v->slug.'/paypal',['event_type'=>'PAYMENT.CAPTURE.COMPLETED','resource'=>['supplementary_data'=>['related_ids'=>['order_id'=>'order-test']]]],$headers)->assertUnauthorized();$this->assertSame(0,$b->payments()->count());}
 public function test_oxxo_signed_notification_verifies_rsa_and_records_once():void{$v=$this->venue();$b=$this->booking($v);$g=$this->account($v,'oxxo');$fixture=json_decode(file_get_contents(__DIR__.'/../Fixtures/oxxo-test-keys.json'),true);$key=openssl_pkey_get_private($fixture['private_key']);$pub=$fixture['public_key'];$g->credentials=['private_key'=>'test-femsa','webhook_public_key'=>$pub];$g->save();$a=$this->attempt($b,$g);$a->update(['external_id'=>'ord_test']);Http::fake(['api.digitalfemsa.io/orders/ord_test'=>Http::response(['id'=>'ord_test','livemode'=>false,'payment_status'=>'paid','amount'=>$a->amount,'amount_refunded'=>0,'currency'=>'MXN','metadata'=>['checkout_id'=>$a->id]])]);$raw=json_encode(['type'=>'order.paid','data'=>['object'=>['id'=>'ord_test']]]);openssl_sign($raw,$signature,$key,OPENSSL_ALGO_SHA256);$this->call('POST','/api/payments/webhooks/'.$v->slug.'/oxxo',[],[],[],['CONTENT_TYPE'=>'application/json','HTTP_ACCEPT'=>'application/json','HTTP_DIGEST'=>base64_encode($signature)],$raw)->assertOk();$this->call('POST','/api/payments/webhooks/'.$v->slug.'/oxxo',[],[],[],['CONTENT_TYPE'=>'application/json','HTTP_ACCEPT'=>'application/json','HTTP_DIGEST'=>base64_encode($signature)],$raw)->assertOk();$this->assertSame(1,$b->payments()->count());$this->assertSame('confirmed',$b->fresh()->status);}
 public function test_checkout_failure_is_not_retried_as_a_second_creation():void{$v=$this->venue();$u=User::factory()->create();$b=$this->booking($v,$u);$this->account($v);Http::fake(['api.mercadopago.com/checkout/preferences'=>Http::response([],503)]);$this->actingAs($u)->postJson('/api/bookings/'.$b->id.'/checkout',['policy_accepted'=>true,'provider'=>'mercadopago','purpose'=>'deposit'])->assertOk()->assertJsonPath('status','unknown');$this->postJson('/api/bookings/'.$b->id.'/checkout',['policy_accepted'=>true,'provider'=>'mercadopago','purpose'=>'deposit'])->assertOk()->assertJsonPath('status','unknown');Http::assertSentCount(1);}
 public function test_reconciliation_command_recovers_missed_notification():void{$v=$this->venue();$b=$this->booking($v);$g=$this->account($v);$a=$this->attempt($b,$g);Http::fake(['api.mercadopago.com/v1/payments/search*'=>Http::response(['results'=>[['id'=>777]]]),'api.mercadopago.com/v1/payments/777'=>Http::response($this->mpData($a))]);$this->artisan('payments:reconcile',['--limit'=>10])->assertSuccessful();$this->assertSame('confirmed',$b->fresh()->status);$this->assertSame(1,$b->payments()->count());}

 public function test_switching_gateway_mode_keeps_old_credentials_for_pending_orders():void{$v=$this->venue();$b=$this->booking($v);$g=$this->account($v);$a=$this->attempt($b,$g);$this->actingAs($v->owner)->putJson('/api/owner/venues/'.$v->slug.'/gateways/mercadopago',['enabled'=>false,'sandbox'=>false,'credentials'=>['access_token'=>'new-live-token','webhook_secret'=>'new-live-secret','merchant_id'=>'12345']])->assertOk();$this->assertSame(2,GatewayAccount::where('venue_id',$v->id)->count());$this->assertFalse($g->fresh()->current);$this->assertSame('test-token',$g->fresh()->credentials['access_token']);config(['portal.kind'=>'client']);\Illuminate\Support\Facades\Auth::forgetGuards();Http::fake(['api.mercadopago.com/v1/payments/777'=>Http::response($this->mpData($a))]);$this->mpNotify($v,$g,777,true)->assertOk();$this->assertSame('confirmed',$b->fresh()->status);}
 public function test_legacy_customer_identity_cannot_view_owner_private_photos():void{\Illuminate\Support\Facades\Storage::fake('local');$u=User::factory()->create();$o=Owner::unguarded(fn()=>Owner::create(['user_id'=>$u->id,'name'=>'Propietario','email'=>$u->email,'password'=>'OwnerPassword12345','activated'=>true,'email_verified_at'=>now()]));$v=$this->venue($o);$photo=$this->actingAs($o)->post('/api/owner/venues/'.$v->slug.'/photos',['photo'=>\Illuminate\Http\UploadedFile::fake()->image('privada.jpg')],['Accept'=>'application/json'])->assertCreated()->json();$this->patchJson('/api/owner/venues/'.$v->slug.'/photos/'.$photo['id'],['visible'=>false])->assertOk();$this->actingAs($u)->get('/api/media/photos/'.$photo['id'])->assertNotFound();}

 public function test_upgrade_preserves_existing_owner_without_reusing_customer_password():void{config(['database.connections.upgrade_test'=>['driver'=>'sqlite','database'=>':memory:','prefix'=>'','foreign_key_constraints'=>true]]);$paths=['database/migrations/0001_01_01_000000_create_users_table.php','database/migrations/0001_01_01_000001_create_cache_table.php','database/migrations/0001_01_01_000002_create_jobs_table.php','database/migrations/2026_10_26_000001_create_booking_platform.php','database/migrations/2026_10_26_000002_add_media_and_payment_ledger.php'];$this->artisan('migrate',['--database'=>'upgrade_test','--path'=>$paths,'--force'=>true])->assertSuccessful();$old=DB::connection('upgrade_test');$password=Hash::make('OldCustomerPassword123');$uid=$old->table('users')->insertGetId(['name'=>'Dueño existente','email'=>'old-owner@example.com','password'=>$password,'created_at'=>now(),'updated_at'=>now()]);$vid=$old->table('venues')->insertGetId(['owner_id'=>$uid,'slug'=>'local-existente','name'=>'Local existente','settings'=>json_encode(VenueSettings::defaults()),'published'=>false,'created_at'=>now(),'updated_at'=>now()]);$this->artisan('migrate',['--database'=>'upgrade_test','--path'=>['database/migrations/2026_10_27_000003_separate_owners_and_checkout.php'],'--force'=>true])->assertSuccessful();$owner=$old->table('owners')->where('user_id',$uid)->first();$this->assertNotNull($owner);$this->assertFalse((bool)$owner->activated);$this->assertNotEquals($password,$owner->password);$this->assertSame($owner->id,$old->table('venues')->where('id',$vid)->value('owner_account_id'));$this->assertSame($password,$old->table('users')->where('id',$uid)->value('password'));}
}
